target.css:
:root {
  --tag-bg: #d9c9a3;
  --tag-border: #7a5c2e;
  --tag-header-bg: #7a5c2e;
  --tag-header-text: #f5ead6;
  --tag-title-color: #f5ead6;
  --tag-number-color: #e0c97a;
  --tag-label-color: #6b4f2a;
  --tag-value-color: #2e1f0e;
  --tag-highlight-color: #7a1a1a;
  --tag-highlight-bg: #f5ead6;
  --tag-footer-bg: #c2a97a;
  --tag-stamp-color: #7a1a1a;
  --tag-date-color: #4a3010;
  --tag-rule: #a08050;
}

body {
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  margin: 0;
}

.ration-tag {
  background-color: var(--tag-bg);
  border: 3px solid var(--tag-border);
  border-radius: 6px;
  width: 300px;
  overflow: hidden;
}

.tag-header {
  background-color: var(--tag-header-bg);
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 10px 14px;
  gap: 8px;
}

.tag-emblem {
  font-size: 22px;
  line-height: 1;
}

.tag-title {
  font-size: 16px;
  font-weight: 800;
  letter-spacing: 0.12em;
  color: var(--tag-title-color);
  margin: 0;
}

.tag-number {
  font-size: 12px;
  font-weight: 600;
  color: var(--tag-number-color);
  letter-spacing: 0.06em;
}

.tag-body {
  padding: 12px 14px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  border-bottom: 2px dashed var(--tag-rule);
}

.tag-row {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.tag-label {
  font-size: 11px;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--tag-label-color);
}

.tag-value {
  font-size: 13px;
  font-weight: 600;
  color: var(--tag-value-color);
}

.tag-highlight {
  background-color: var(--tag-highlight-bg);
  color: var(--tag-highlight-color);
  font-weight: 800;
  border: 1px solid var(--tag-highlight-color);
  border-radius: 4px;
  padding: 2px 8px;
}

.tag-footer {
  background-color: var(--tag-footer-bg);
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 8px 14px;
}

.tag-stamp {
  font-size: 11px;
  font-weight: 800;
  letter-spacing: 0.14em;
  color: var(--tag-stamp-color);
  border: 2px solid var(--tag-stamp-color);
  border-radius: 3px;
  padding: 2px 6px;
}

.tag-date {
  font-size: 12px;
  font-weight: 600;
  color: var(--tag-date-color);
  letter-spacing: 0.05em;
}

